import React from 'react';
import PageHeader from './PageHeader';

interface VideoItem {
  id: string;
  title: string;
  description: string;
  date: string;
  event: string;
  thumbnail: string;
  videoUrl: string;
  duration?: string;
  tags: string[];
  requiresRegistration?: boolean;
}

const PublicSpeaking: React.FC = () => {
  const videos: VideoItem[] = [
    {
      id: '1',
      title: 'Le HPC pour vous aider à voir vraiment grand!',
      description: 'Découvrez les dernières innovations AWS pour le calcul haute performance : AWS Parallel Compute Service (PCS), AWS Batch et réservation EC2. Avec le témoignage d\'EDF R&D et leurs 11 Pétaflops d\'expérience HPC cloud.',
      date: '2025-04-04',
      event: 'AWS Paris Summit 2025',
      thumbnail: '/images/speaking/Screenshot 2025-06-27 at 21.41.48.png',
      videoUrl: 'https://summitparis.awslivestream.com/v-app201/live/',
      duration: '45:00',
      tags: ['HPC', 'High Performance Computing', 'AWS PCS', 'AWS Batch', 'EDF'],
      requiresRegistration: true
    },
