import React, { useState, useEffect, useCallback } from 'react';
import PageHeader from './PageHeader';

interface Fish {
  id: number;
  x: number;
  y: number;
  type: 'fish' | 'shark' | 'treasure';
  emoji: string;
  speed: number;
  direction: number;
}

interface GameState {
  diverX: number;
  diverY: number;
  depth: number;
  oxygen: number;
  score: number;
  gameOver: boolean;
  gameStarted: boolean;
  fish: Fish[];
  treasures: number;
}

const TryMe: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    diverX: 400,
    diverY: 300,
    depth: 0,
    oxygen: 100,
    score: 0,
    gameOver: false,
    gameStarted: false,
    fish: [],
    treasures: 0
  });

  const [keys, setKeys] = useState<Set<string>>(new Set());

  // Initialize fish
  const initializeFish = useCallback(() => {
    const newFish: Fish[] = [];
    for (let i = 0; i < 15; i++) {
      newFish.push({
        id: i,
        x: Math.random() * 800,
        y: Math.random() * 500 + 100,
        type: Math.random() < 0.1 ? 'shark' : Math.random() < 0.2 ? 'treasure' : 'fish',
        emoji: Math.random() < 0.1 ? '🦈' : Math.random() < 0.2 ? '💎' : ['🐠', '🐟', '🦑', '🐙', '🦀'][Math.floor(Math.random() * 5)],
        speed: Math.random() * 2 + 1,
        direction: Math.random() * Math.PI * 2
      });
    }
    return newFish;
  }, []);

  // Start game
  const startGame = () => {
    setGameState({
      diverX: 400,
      diverY: 300,
      depth: 0,
      oxygen: 100,
      score: 0,
      gameOver: false,
      gameStarted: true,
      fish: initializeFish(),
      treasures: 0
    });
  };

  // Handle keyboard input
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      setKeys(prev => new Set(prev).add(e.key.toLowerCase()));
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      setKeys(prev => {
        const newKeys = new Set(prev);
        newKeys.delete(e.key.toLowerCase());
        return newKeys;
      });
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  // Game loop
  useEffect(() => {
    if (!gameState.gameStarted || gameState.gameOver) return;

    const gameLoop = setInterval(() => {
      setGameState(prev => {
        let newDiverX = prev.diverX;
        let newDiverY = prev.diverY;
        let newDepth = prev.depth;
        let newOxygen = prev.oxygen;

        // Handle movement
        if (keys.has('arrowleft') || keys.has('a')) newDiverX = Math.max(0, newDiverX - 5);
        if (keys.has('arrowright') || keys.has('d')) newDiverX = Math.min(750, newDiverX + 5);
        if (keys.has('arrowup') || keys.has('w')) {
          newDiverY = Math.max(50, newDiverY - 5);
          newDepth = Math.max(0, newDepth - 0.5);
        }
        if (keys.has('arrowdown') || keys.has('s')) {
          newDiverY = Math.min(550, newDiverY + 5);
          newDepth = Math.min(60, newDepth + 0.5);
        }

        // Oxygen consumption (more at depth)
        const oxygenConsumption = 0.2 + (newDepth / 60) * 0.3;
        newOxygen = Math.max(0, newOxygen - oxygenConsumption);

        // Move fish
        const newFish = prev.fish.map(fish => {
          let newX = fish.x + Math.cos(fish.direction) * fish.speed;
          let newY = fish.y + Math.sin(fish.direction) * fish.speed;

          // Bounce off walls
          if (newX <= 0 || newX >= 800) fish.direction = Math.PI - fish.direction;
          if (newY <= 100 || newY >= 600) fish.direction = -fish.direction;

          newX = Math.max(0, Math.min(800, newX));
          newY = Math.max(100, Math.min(600, newY));

          return { ...fish, x: newX, y: newY };
        });

        // Check collisions
        let newScore = prev.score;
        let newTreasures = prev.treasures;
        let gameOver = false;

        const remainingFish = newFish.filter(fish => {
          const distance = Math.sqrt(
            Math.pow(fish.x - newDiverX, 2) + Math.pow(fish.y - newDiverY, 2)
          );

          if (distance < 30) {
            if (fish.type === 'shark') {
              gameOver = true;
              return true;
            } else if (fish.type === 'treasure') {
              newScore += 50;
              newTreasures += 1;
              return false; // Remove treasure
            } else {
              newScore += 10;
              return false; // Remove fish
            }
          }
          return true;
        });

        // Game over conditions
        if (newOxygen <= 0) gameOver = true;

        return {
          ...prev,
          diverX: newDiverX,
          diverY: newDiverY,
          depth: newDepth,
          oxygen: newOxygen,
          score: newScore,
          treasures: newTreasures,
          fish: remainingFish,
          gameOver
        };
      });
    }, 50);

    return () => clearInterval(gameLoop);
  }, [gameState.gameStarted, gameState.gameOver, keys]);

  return (
    <div className="sitepage try-me">
      <PageHeader aTitle="Try Me" />

      <div className="game-intro">
        <p>
          🤿 <strong>Scuba Diving Mini-Game</strong> - This game was entirely coded by Amazon Q (Claude)! 
          Use arrow keys or WASD to navigate underwater, collect fish and treasures, but avoid sharks! 
          Watch your oxygen levels - the deeper you go, the faster it depletes.
        </p>
      </div>

      {!gameState.gameStarted ? (
        <div className="game-start">
          <button onClick={startGame} className="start-button">
            🌊 Start Diving Adventure
          </button>
          <div className="game-instructions">
            <h3>🎮 How to Play</h3>
            <ul>
              <li>🏊‍♂️ Use <strong>Arrow Keys</strong> or <strong>WASD</strong> to move</li>
              <li>🐠 Collect fish (+10 points each)</li>
              <li>💎 Find treasures (+50 points each)</li>
              <li>🦈 Avoid sharks (game over!)</li>
              <li>💨 Watch your oxygen - surface regularly!</li>
              <li>🌊 Deeper diving consumes more oxygen</li>
            </ul>
          </div>
        </div>
      ) : (
        <div className="game-container">
          <div className="game-stats">
            <div className="stat">
              <span className="stat-label">Score:</span>
              <span className="stat-value">{gameState.score}</span>
            </div>
            <div className="stat">
              <span className="stat-label">Depth:</span>
              <span className="stat-value">{Math.round(gameState.depth)}m</span>
            </div>
            <div className="stat">
              <span className="stat-label">Treasures:</span>
              <span className="stat-value">{gameState.treasures}</span>
            </div>
            <div className="stat">
              <span className="stat-label">Oxygen:</span>
              <div className="oxygen-bar">
                <div 
                  className="oxygen-fill" 
                  style={{ width: `${gameState.oxygen}%` }}
                ></div>
              </div>
              <span className="stat-value">{Math.round(gameState.oxygen)}%</span>
            </div>
          </div>

          <div className="game-area">
            {/* Water surface */}
            <div className="water-surface"></div>

            {/* Diver */}
            <div 
              className="diver" 
              style={{ 
                left: `${gameState.diverX}px`, 
                top: `${gameState.diverY}px` 
              }}
            >
              🤿
            </div>

            {/* Fish */}
            {gameState.fish.map(fish => (
              <div
                key={fish.id}
                className={`sea-creature ${fish.type}`}
                style={{
                  left: `${fish.x}px`,
                  top: `${fish.y}px`
                }}
              >
                {fish.emoji}
              </div>
            ))}

            {/* Depth indicator */}
            <div className="depth-indicator">
              <div className="depth-line" style={{ top: '100px' }}>Surface</div>
              <div className="depth-line" style={{ top: '200px' }}>10m</div>
              <div className="depth-line" style={{ top: '300px' }}>20m</div>
              <div className="depth-line" style={{ top: '400px' }}>30m</div>
              <div className="depth-line" style={{ top: '500px' }}>40m</div>
            </div>
          </div>

          {gameState.gameOver && (
            <div className="game-over">
              <div className="game-over-content">
                <h2>🌊 Dive Complete!</h2>
                <p>Final Score: <strong>{gameState.score}</strong></p>
                <p>Treasures Found: <strong>{gameState.treasures}</strong></p>
                <p>Max Depth: <strong>{Math.round(gameState.depth)}m</strong></p>
                {gameState.oxygen <= 0 && <p className="death-reason">💨 Ran out of oxygen!</p>}
                {gameState.fish.some(f => f.type === 'shark') && <p className="death-reason">🦈 Shark encounter!</p>}
                <button onClick={startGame} className="restart-button">
                  🔄 Dive Again
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      <div className="game-footer">
        <p>
          💡 <strong>Fun Fact:</strong> This mini-game combines my passion for scuba diving with coding! 
          As a certified diving instructor, I know that proper oxygen management and awareness of your surroundings 
          are crucial underwater - just like in cloud architecture! 🤿☁️
        </p>
      </div>
    </div>
  );
};

export default TryMe;

