  top: 100px;
  left: 0;
  right: 0;
  height: 2px;
  background: rgba(255, 255, 255, 0.5);
  box-shadow: 0 0 10px rgba(255, 255, 255, 0.3);
}

.try-me .diver {
  position: absolute;
  font-size: 2rem;
  transition: all 0.1s ease;
  z-index: 10;
  filter: drop-shadow(2px 2px 4px rgba(0,0,0,0.3));
}

.try-me .sea-creature {
  position: absolute;
  font-size: 1.5rem;
  transition: all 0.1s ease;
  user-select: none;
}

.try-me .sea-creature.shark {
  font-size: 2rem;
  filter: drop-shadow(2px 2px 4px rgba(255,0,0,0.5));
}

.try-me .sea-creature.treasure {
  font-size: 1.2rem;
  animation: sparkle 2s infinite;
}

@keyframes sparkle {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.2); }
}

.try-me .depth-indicator {
  position: absolute;
  left: 10px;
  top: 0;
  bottom: 0;
  width: 80px;
  pointer-events: none;
}

.try-me .depth-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: rgba(255, 255, 255, 0.3);
  font-size: 0.8rem;
  color: rgba(255, 255, 255, 0.7);
  padding-left: 5px;
}

.try-me .game-over {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.8);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-lg);
}

.try-me .game-over-content {
  background: var(--bg-primary);
  padding: 2rem;
  border-radius: var(--radius-lg);
  text-align: center;
  max-width: 400px;
}

.try-me .game-over-content h2 {
  color: var(--text-primary);
  margin-bottom: 1rem;
}

.try-me .game-over-content p {
  color: var(--text-secondary);
  margin-bottom: 0.5rem;
}

.try-me .death-reason {
  color: #ff4444 !important;
  font-weight: 600;
}

.try-me .restart-button {
  background: linear-gradient(135deg, #0077be, #00a8cc);
  color: white;
  border: none;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all 0.3s ease;
  margin-top: 1rem;
}

.try-me .restart-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 15px rgba(0, 119, 190, 0.3);
}

.try-me .game-footer {
  background: var(--bg-tertiary);
  padding: 1.5rem;
  border-radius: var(--radius-lg);
  text-align: center;
  border-left: 4px solid var(--primary-color);
}

.try-me .game-footer p {
  color: var(--text-primary);
  line-height: 1.6;
  margin: 0;
}

/* Responsive Design for Game */
@media (max-width: 900px) {
  .try-me .game-area {
    width: 100%;
    max-width: 800px;
    height: 500px;
  }

  .try-me .game-stats {
    flex-direction: column;
    gap: 0.5rem;
  }

  .try-me .stat {
    justify-content: center;
  }
}

@media (max-width: 600px) {
  .try-me .game-area {
    height: 400px;
  }

  .try-me .diver {
    font-size: 1.5rem;
  }

  .try-me .sea-creature {
    font-size: 1.2rem;
  }

  .try-me .sea-creature.shark {
    font-size: 1.5rem;
  }
}

