args.new_str:
// Initialize fish
const initializeFish = useCallback(() => {
  const newFish: Fish[] = [];
  for (let i = 0; i < 15; i++) {
    const fishType = Math.random();
    let type: 'fish' | 'shark' | 'treasure';
    let emoji: string;

    if (fishType < 0.1) {
      type = 'shark';
      emoji = '🦈';
    } else if (fishType < 0.2) {
      type = 'treasure';
      emoji = '💎';
    } else {
      type = 'fish';
      emoji = ['🐠', '🐟', '🦑', '🐙', '🦀'][Math.floor(Math.random() * 5)];
    }

    newFish.push({
      id: i,
      x: Math.random() * 700 + 50, // Keep away from edges
      y: Math.random() * 400 + 150, // Keep below surface
      type,
      emoji,
      speed: type === 'shark' ? Math.random() * 1.5 + 2 : Math.random() * 2 + 1, // Sharks are faster
      direction: Math.random() * Math.PI * 2
    });
  }
  return newFish;
}, []);

