args.new_str:
// Move fish
const newFish = prev.fish.map(fish => {
  let newX = fish.x + Math.cos(fish.direction) * fish.speed;
  let newY = fish.y + Math.sin(fish.direction) * fish.speed;

  // Bounce off walls
  if (newX <= 0 || newX >= 700) fish.direction = Math.PI - fish.direction;
  if (newY <= 100 || newY >= 500) fish.direction = -fish.direction;

  newX = Math.max(0, Math.min(700, newX));
  newY = Math.max(100, Math.min(500, newY));

  return { ...fish, x: newX, y: newY };
});

