  depth: number;
  oxygen: number;
  score: number;
  gameOver: boolean;
  gameStarted: boolean;
  fish: Fish[];
  treasures: number;
  level: number;
  powerUps: string[];
  invulnerable: number;
  turboMode: number;
  lightRadius: number;
  combo: number;
  maxCombo: number;
}

