// Initialize fish with more variety and special creatures
const initializeFish = useCallback((level: number = 1) => {
  const newFish: Fish[] = [];
  const fishCount = Math.min(20, 12 + level * 2);

  for (let i = 0; i < fishCount; i++) {
    const rand = Math.random();
    let type: Fish['type'];
    let emoji: string;
    let speed: number;
    let size: number = 1;

    if (rand < 0.05) {
      type = 'whale';
      emoji = '🐋';
      speed = 0.5;
      size = 3;
    } else if (rand < 0.1) {
      type = 'submarine';
      emoji = '🚢';
      speed = 1;
      size = 2;
    } else if (rand < 0.15) {
      type = 'octopus';
      emoji = '🐙';
      speed = 1.5;
    } else if (rand < 0.2) {
      type = 'jellyfish';
      emoji = '🪼';
      speed = 0.8;
    } else if (rand < 0.25 + level * 0.02) {
      type = 'shark';
      emoji = '🦈';
      speed = 2 + level * 0.3;
    } else if (rand < 0.35) {
      type = 'treasure';
      emoji = ['💎', '👑', '🏆', '💰', '⚱️'][Math.floor(Math.random() * 5)];
      speed = 0;
    } else if (rand < 0.45) {
      type = 'bubble';
      emoji = '💨';
      speed = -1; // Bubbles go up
    } else {
      type = 'fish';
      emoji = ['🐠', '🐟', '🦑', '🦀', '🦞', '🐡', '🦭'][Math.floor(Math.random() * 7)];
      speed = Math.random() * 2 + 1;
    }

    newFish.push({
      id: i,
      x: Math.random() * 600 + 50,
      y: Math.random() * 350 + 150,
      type,
      emoji,
      speed,
      direction: Math.random() * Math.PI * 2,
      size,
      health: type === 'octopus' ? 2 : 1,
      bubbleTimer: type === 'bubble' ? Math.random() * 100 : 0
    });
  }
  return newFish;
}, []);

