// Game loop with advanced mechanics
useEffect(() => {
  if (!gameState.gameStarted || gameState.gameOver) return;

  const gameLoop = setInterval(() => {
    setGameState(prev => {
      let newDiverX = prev.diverX;
      let newDiverY = prev.diverY;
      let newDepth = prev.depth;
      let newOxygen = prev.oxygen;
      const moveSpeed = prev.turboMode > 0 ? 8 : 5;

      // Handle movement with turbo mode
      if (keys.has('arrowleft') || keys.has('a')) newDiverX = Math.max(0, newDiverX - moveSpeed);
      if (keys.has('arrowright') || keys.has('d')) newDiverX = Math.min(650, newDiverX + moveSpeed);
      if (keys.has('arrowup') || keys.has('w')) {
        newDiverY = Math.max(50, newDiverY - moveSpeed);
        newDepth = Math.max(0, newDepth - 0.8);
      }
      if (keys.has('arrowdown') || keys.has('s')) {
        newDiverY = Math.min(450, newDiverY + moveSpeed);
        newDepth = Math.min(80, newDepth + 0.8);
      }

      // Advanced oxygen management
      if (newDepth <= 2) {
        newOxygen = Math.min(100, newOxygen + 1.2);
      } else {
        const baseConsumption = 0.12;
        const depthMultiplier = (newDepth / 80) * 0.3;
        const turboMultiplier = prev.turboMode > 0 ? 1.5 : 1;
        newOxygen = Math.max(0, newOxygen - (baseConsumption + depthMultiplier) * turboMultiplier);
      }

      // Move creatures with advanced AI
      const newFish = prev.fish.map(fish => {
        let newX = fish.x;
        let newY = fish.y;
        let newDirection = fish.direction;

        if (fish.type === 'bubble') {
          // Bubbles float up and disappear
          newY -= 2;
          if (newY < 50) return null; // Remove bubble
        } else if (fish.type === 'whale') {
          // Whales move slowly and majestically
          newX += Math.cos(fish.direction) * fish.speed;
          newY += Math.sin(fish.direction) * 0.2; // Slight vertical movement
        } else if (fish.type === 'shark') {
          // Sharks hunt the player if close enough
          const distanceToPlayer = Math.sqrt(
            Math.pow(fish.x - newDiverX, 2) + Math.pow(fish.y - newDiverY, 2)
          );

          if (distanceToPlayer < 150 && prev.invulnerable <= 0) {
            // Chase player
            const angleToPlayer = Math.atan2(newDiverY - fish.y, newDiverX - fish.x);
            newDirection = angleToPlayer;
          }

          newX += Math.cos(newDirection) * fish.speed;
          newY += Math.sin(newDirection) * fish.speed;
        } else if (fish.type === 'jellyfish') {
          // Jellyfish drift and pulse
          newX += Math.cos(fish.direction) * fish.speed;
          newY += Math.sin(fish.direction + Math.sin(Date.now() * 0.01) * 0.5) * fish.speed;
        } else if (fish.type === 'octopus') {
          // Octopus moves erratically
          if (Math.random() < 0.1) {
            newDirection = Math.random() * Math.PI * 2;
          }
          newX += Math.cos(newDirection) * fish.speed;
          newY += Math.sin(newDirection) * fish.speed;
        } else if (fish.type !== 'treasure' && fish.type !== 'submarine') {
          // Regular fish movement
          newX += Math.cos(fish.direction) * fish.speed;
          newY += Math.sin(fish.direction) * fish.speed;
        }

        // Bounce off walls
        if (newX <= 0 || newX >= 700) newDirection = Math.PI - newDirection;
        if (newY <= 100 || newY >= 500) newDirection = -newDirection;

        newX = Math.max(0, Math.min(700, newX));
        newY = Math.max(100, Math.min(500, newY));

        return { ...fish, x: newX, y: newY, direction: newDirection };
      }).filter(Boolean) as Fish[];

      // Advanced collision detection and scoring
      let newScore = prev.score;
      let newTreasures = prev.treasures;
      let newCombo = prev.combo;
      let newMaxCombo = prev.maxCombo;
      let newPowerUps = [...prev.powerUps];
      let newInvulnerable = Math.max(0, prev.invulnerable - 1);
      let newTurboMode = Math.max(0, prev.turboMode - 1);
      let newLightRadius = prev.lightRadius;
      let gameOver = false;

      const remainingFish = newFish.filter(fish => {
        const distance = Math.sqrt(
          Math.pow(fish.x - newDiverX, 2) + Math.pow(fish.y - newDiverY, 2)
        );

        if (distance < 35) {
          if (fish.type === 'shark' && newInvulnerable <= 0) {
            gameOver = true;
            return true;
          } else if (fish.type === 'whale') {
            // Whale gives massive bonus and temporary invulnerability
            newScore += 200;
            newInvulnerable = 180; // 3 seconds
            newPowerUps.push('🐋 Whale Protection!');
            newCombo = 0;
            return false;
          } else if (fish.type === 'submarine') {
            // Submarine gives oxygen boost and light
            newOxygen = Math.min(100, newOxygen + 30);
            newLightRadius = 150;
            newPowerUps.push('🚢 Submarine Rescue!');
            newScore += 100;
            newCombo++;
            return false;
          } else if (fish.type === 'treasure') {
            const treasureBonus = 50 + (newCombo * 10);
            newScore += treasureBonus;
            newTreasures += 1;
            newCombo++;
            newMaxCombo = Math.max(newMaxCombo, newCombo);
            return false;
          } else if (fish.type === 'bubble') {
            // Bubble gives oxygen
            newOxygen = Math.min(100, newOxygen + 15);
            newScore += 5;
            return false;
          } else if (fish.type === 'jellyfish') {
            // Jellyfish stuns briefly but gives points
            newScore += 30;
            newTurboMode = 120; // 2 seconds of turbo
            newPowerUps.push('🪼 Jellyfish Boost!');
            newCombo++;
            return false;
          } else if (fish.type === 'octopus') {
            // Octopus requires multiple hits
            if (fish.health && fish.health > 1) {
              fish.health--;
              fish.stunned = true;
              newScore += 20;
              return true;
            } else {
              newScore += 80;
              newCombo++;
              return false;
            }
          } else {
            // Regular fish
            const fishBonus = 10 + (newCombo * 2);
            newScore += fishBonus;
            newCombo++;
            newMaxCombo = Math.max(newMaxCombo, newCombo);
            return false;
          }
        }
        return true;
      });

      // Level progression
      let newLevel = prev.level;
      if (newScore > prev.level * 500) {
        newLevel++;
        // Add new creatures for next level
        const levelFish = initializeFish(newLevel);
        remainingFish.push(...levelFish.slice(0, 3)); // Add 3 new creatures
        newPowerUps.push(`🎉 Level ${newLevel} Reached!`);
      }

      // Clean up old power-up messages
      if (newPowerUps.length > 3) {
        newPowerUps = newPowerUps.slice(-3);
      }

      // Game over conditions
      if (newOxygen <= 0) gameOver = true;

      return {
        ...prev,
        diverX: newDiverX,
        diverY: newDiverY,
        depth: newDepth,
        oxygen: newOxygen,
        score: newScore,
        treasures: newTreasures,
        fish: remainingFish,
        gameOver,
        level: newLevel,
        powerUps: newPowerUps,
        invulnerable: newInvulnerable,
        turboMode: newTurboMode,
        lightRadius: newLightRadius,
        combo: newCombo,
        maxCombo: newMaxCombo
      };
    });
  }, 50);

  return () => clearInterval(gameLoop);
}, [gameState.gameStarted, gameState.gameOver, keys, initializeFish]);

