  // Bubbles float up faster and disappear
  newY -= 3; // Increased speed
  if (newY < 50) return null;
} else if (fish.type === 'whale') {
  // Whales move more dynamically
  newX += Math.cos(fish.direction) * fish.speed * 1.5; // Faster movement
  newY += Math.sin(fish.direction) * 0.3;
} else if (fish.type === 'shark') {
  // More aggressive shark AI
  const distanceToPlayer = Math.sqrt(
    Math.pow(fish.x - newDiverX, 2) + Math.pow(fish.y - newDiverY, 2)
  );

  if (distanceToPlayer < 200 && prev.invulnerable <= 0) { // Increased detection range
    const angleToPlayer = Math.atan2(newDiverY - fish.y, newDiverX - fish.x);
    newDirection = angleToPlayer;
  }

  newX += Math.cos(newDirection) * fish.speed * 1.2; // Faster sharks
  newY += Math.sin(newDirection) * fish.speed * 1.2;
} else if (fish.type === 'jellyfish') {
  // More dynamic jellyfish movement
  newX += Math.cos(fish.direction) * fish.speed * 1.3;
  newY += Math.sin(fish.direction + Math.sin(Date.now() * 0.02) * 0.8) * fish.speed * 1.3;
} else if (fish.type === 'octopus') {
  // More erratic octopus behavior
  if (Math.random() < 0.15) { // More frequent direction changes
    newDirection = Math.random() * Math.PI * 2;
  }
  newX += Math.cos(newDirection) * fish.speed * 1.4;
  newY += Math.sin(newDirection) * fish.speed * 1.4;
} else if (fish.type !== 'treasure' && fish.type !== 'submarine') {
  // Faster regular fish movement
  newX += Math.cos(fish.direction) * fish.speed * 1.3;
