args.new_str:
// Initialize fish with more variety and special creatures
const initializeFish = useCallback((level: number = 1) => {
  const newFish: Fish[] = [];
  const fishCount = Math.min(18, 12 + level * 1); // Reduced creature spawn rate

  for (let i = 0; i < fishCount; i++) {
    const rand = Math.random();
    let type: Fish['type'];
    let emoji: string;
    let speed: number;
    let size: number = 1;

    if (rand < 0.03) { // Reduced whale spawn rate
      type = 'whale';
      emoji = '🐋';
      speed = 0.8;
      size = 3;
    } else if (rand < 0.06) { // Reduced submarine spawn rate
      type = 'submarine';
      emoji = '🚢';
      speed = 1;
      size = 2;
    } else if (rand < 0.12) {
      type = 'octopus';
      emoji = '🐙';
      speed = 1.5;
    } else if (rand < 0.18) {
      type = 'jellyfish';
      emoji = '🪼';
      speed = 0.8;
    } else if (rand < 0.22 + level * 0.01) { // Slightly increased shark spawn with level
      type = 'shark';
      emoji = '🦈';
      speed = 2 + level * 0.2; // Reduced speed scaling
    } else if (rand < 0.35) {
      type = 'treasure';
      emoji = ['💎', '👑', '🏆', '💰', '⚱️'][Math.floor(Math.random() * 5)];
      speed = 0;
    } else if (rand < 0.45) {
      type = 'bubble';
      emoji = '💨';
      speed = -1;
    } else {
      type = 'fish';
      emoji = ['🐠', '🐟', '🦑', '🦀', '🦞', '🐡', '🦭'][Math.floor(Math.random() * 7)];
      speed = Math.random() * 2 + 1;
    }

    newFish.push({
      id: Date.now() + i, // Better unique ID generation
      x: Math.random() * 600 + 50,
      y: Math.random() * 350 + 150,
      type,
      emoji,
      speed,
      direction: Math.random() * Math.PI * 2,
      size,
      health: type === 'octopus' ? 2 : 1,
      bubbleTimer: type === 'bubble' ? Math.random() * 100 : 0
    });
  }
  return newFish;
}, []);

