// Initialize fish with balanced spawn rates
const initializeFish = useCallback((level: number = 1) => {
  const newFish: Fish[] = [];
  const fishCount = Math.min(15, 10 + level); // Reduced base count

  for (let i = 0; i < fishCount; i++) {
    const rand = Math.random();
    let type: Fish['type'];
    let emoji: string;
    let speed: number;
    let size: number = 1;
    let x: number, y: number;

    // Ensure safe spawn positions (not near player start position 350, 300)
    do {
      x = Math.random() * 600 + 50;
      y = Math.random() * 350 + 150;
    } while (Math.sqrt(Math.pow(x - 350, 2) + Math.pow(y - 300, 2)) < 100); // Keep 100px away from player

    if (rand < 0.02) { // Very rare whales
      type = 'whale';
      emoji = '🐋';
      speed = 0.8;
      size = 3;
    } else if (rand < 0.04) { // Very rare submarines
      type = 'submarine';
      emoji = '🚢';
      speed = 1;
      size = 2;
    } else if (rand < 0.1) {
      type = 'octopus';
      emoji = '🐙';
      speed = 1.2;
    } else if (rand < 0.15) {
      type = 'jellyfish';
      emoji = '🪼';
      speed = 0.8;
    } else if (rand < 0.15 + level * 0.015) { // Gradual shark increase
      type = 'shark';
      emoji = '🦈';
