const currentFish = newFish.filter(f => f.type === 'fish').length;
const totalCreatures = newFish.length;

// Respawn creatures if needed
if (totalCreatures < minCreatures || currentSharks < 1 || currentFish < 3) {
  const respawnCount = Math.max(minCreatures - totalCreatures, 0);
