      x,
      y,
      type: 'shark',
      emoji: '🦈',
      speed: 1.8 + newLevel * 0.1,
      direction: Math.random() * Math.PI * 2,
      health: 1
    });
  }

  // Add needed fish
  for (let i = 0; i < fishNeeded; i++) {
    let x, y;
    do {
      x = Math.random() * 600 + 50;
      y = Math.random() * 350 + 150;
    } while (Math.sqrt(Math.pow(x - newDiverX, 2) + Math.pow(y - newDiverY, 2)) < 100);

