      speed: Math.random() * 1.5 + 1,
      direction: Math.random() * Math.PI * 2,
      health: 1
    });
  }

  // Add some variety creatures if total is still low
  const varietyNeeded = Math.max(0, respawnCount - sharksNeeded - fishNeeded);
  for (let i = 0; i < varietyNeeded; i++) {
    let x, y;
    do {
      x = Math.random() * 600 + 50;
      y = Math.random() * 350 + 150;
    } while (Math.sqrt(Math.pow(x - newDiverX, 2) + Math.pow(y - newDiverY, 2)) < 100);

    const rand = Math.random();
    let type: Fish['type'], emoji: string, speed: number;

    if (rand < 0.3) {
      type = 'treasure';
      emoji = ['💎', '👑', '💰'][Math.floor(Math.random() * 3)];
      speed = 0;
    } else if (rand < 0.5) {
      type = 'bubble';
      emoji = '💨';
      speed = -1;
    } else if (rand < 0.7) {
      type = 'jellyfish';
      emoji = '🪼';
      speed = 0.8;
    } else {
      type = 'octopus';
      emoji = '🐙';
      speed = 1.2;
    }

    newFish.push({
      id: Date.now() + Math.random() * 10000,
      x,
      y,
      type,
      emoji,
      speed,
      direction: Math.random() * Math.PI * 2,
      health: type === 'octopus' ? 2 : 1
    });
  }
}

