import React from 'react';
import PageHeader from './PageHeader';



const About: React.FC = () => {
  return (
    <div className="sitepage">
      <PageHeader aTitle="About Me"/>
      <p>
      I am Sébastien, an IT Engineer with an unrivaled passion for technology, from personal drones to space rockets.
      <br/>
      My <strong>two decades of experience</strong> have positioned me as a driving force in <strong>innovation and digital transformation</strong>.
<br/><br/>
As Principal Solutions Architect at AWS, I lead large-scale, complex projects that revolutionize businesses through <strong>cloud technologies</strong>. I spearheaded France's largest AWS-based digital transformation project, guiding a major French enterprise in a sensitive sector through their cloud adoption journey.
<br/><br/>
My expertise lies in aligning technical choices with business objectives, a skill I've leveraged as the <strong>leader of the Cybersecurity Practice</strong> in France for AWS. I am at the forefront of AI/ML implementation, successfully deploying these solutions at scale to transform businesses.
<br/><br/>
Leadership and mentorship are the cornerstones of my professional approach. I build and lead high-performing teams, translating complex technical concepts into actionable strategies for both C-suite executives and technical teams.
<br/><br/>
I also bring the experience gained from 18 years as an <strong>innovation leader at Eutelsat</strong>, a leading satellite operator. There, I filed three patents and honed my skills in strategic technological advancement.
<br/><br/>
I am a recognized thought leader in cloud computing, committed to pushing boundaries and exploring how cloud technologies drive unprecedented growth. If you're ready to embark on a transformative cloud journey or elevate your existing strategy, I am the expert you need to bring your vision to life. Let's collaborate and create groundbreaking solutions together.
</p>
    </div>
  );
};

export default About;

